INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss ich Hardware immer manuell konfigurieren?', 2, '[{"text": "Nein", "correct": true, "because": "Automatische Erkennung oft möglich"}, {"text": "Ja", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Dienst konfiguriere ich für Webzugriff?', 3, '[{"text": "HTTP-Server", "correct": true, "because": "Ermöglicht Website-Bereitstellung"}, {"text": "DNS-Server", "correct": false, "because": "Nur Namensauflösung"}, {"text": "DHCP-Server", "correct": false, "because": "IP-Vergabe, kein Web"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Hardwarekonfiguration für Server effektiv?', 5, '[{"text": "Optimierte Ressourcen", "correct": true, "because": "Passend zu Diensten"}, {"text": "Redundanz", "correct": true, "because": "Schutz vor Ausfällen"}, {"text": "Minimale Leistung", "correct": false, "because": "Nicht ausreichend"}, {"text": "Einfache Bedienung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Dienste brauchen spezifische Ports. b) Hardwarekonfiguration ist OS-unabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, OS beeinflusst"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Konfiguration eines Dateiservers?', 4, '[{"text": "Speicherzuweisung", "correct": false, "because": "Kern der Funktion"}, {"text": "Netzwerkkonnektivität", "correct": false, "because": "Zugriff nötig"}, {"text": "Gaming-Optimierung", "correct": true, "because": "Irrelevant für Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCP automatisch IPs vergibt?', 2, '[{"text": "Ja", "correct": true, "because": "Dynamische Zuweisung"}, {"text": "Nein", "correct": false, "because": "Hauptfunktion von DHCP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hardware-Feature priorisiere ich für einen Datenbankdienst?', 3, '[{"text": "Schnelle SSDs", "correct": true, "because": "I/O ist entscheidend"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Nicht relevant"}, {"text": "Geringer RAM", "correct": false, "because": "Mehr RAM besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Dienstkonfiguration?', 5, '[{"text": "Stabilität", "correct": true, "because": "Weniger Abstürze"}, {"text": "Effizienz", "correct": true, "because": "Optimierte Ressourcennutzung"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht direkt"}, {"text": "Einfache Installation", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Hardwarekonfiguration beeinflusst Dienste. b) Alle Dienste laufen auf jeder Hardware. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Hardware limitiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Konfiguration eines Druckerservers?', 4, '[{"text": "Netzwerkverbindung", "correct": false, "because": "Zugriff nötig"}, {"text": "Druckertreiber", "correct": false, "because": "Kompatibilität erforderlich"}, {"text": "Hohe CPU-Leistung", "correct": true, "because": "Nicht primär nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ich Dienste immer neu starten nach Konfigurationsänderungen?', 2, '[{"text": "Ja", "correct": true, "because": "Änderungen wirksam machen"}, {"text": "Nein", "correct": false, "because": "Selten ohne Neustart"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die Hardware eines Webservers wichtig?', 4, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Viele Anfragen"}, {"text": "Schneller Prozessor", "correct": true, "because": "Schnelle Verarbeitung"}, {"text": "Großer Cache", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Hardwarekonfiguration keine Rolle spielt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Leistung beeinflusst Dienste"}, {"text": "Ja", "correct": false, "because": "Hardware ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Konfiguration eines DNS-Servers?', 3, '[{"text": "Schnelle Antwortzeiten", "correct": true, "because": "Effiziente Namensauflösung"}, {"text": "Maximale Speicherkapazität", "correct": false, "because": "Sekundär"}, {"text": "Grafische Tools", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Dienste brauchen spezifische Hardware. b) Konfiguration ist einmalig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Änderungen nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schlechte Hardwarekonfiguration?', 5, '[{"text": "Leistungseinbußen", "correct": true, "because": "Dienste langsamer"}, {"text": "Instabilität", "correct": true, "because": "Häufige Abstürze"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht vorteilhaft"}, {"text": "Einfachere Wartung", "correct": false, "because": "Komplexer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Konfiguration eines Mailservers unwichtig?', 3, '[{"text": "Netzwerkverbindung", "correct": false, "because": "Kern der Funktion"}, {"text": "Sicherheitsprotokolle", "correct": false, "because": "Schutz nötig"}, {"text": "Hohe Grafikleistung", "correct": true, "because": "Irrelevant für Mail"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Beeinflusst die Hardware die Dienstleistung?', 3, '[{"text": "Ja", "correct": true, "because": "Ressourcen bestimmen Performance"}, {"text": "Nein", "correct": false, "because": "Hardware ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Dienste ohne Konfiguration laufen?', 2, '[{"text": "Nein", "correct": true, "because": "Grundkonfiguration nötig"}, {"text": "Ja", "correct": false, "because": "Selten ohne Einstellungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardware wähle ich für einen Virtualisierungsdienst?', 4, '[{"text": "Hohe CPU-Leistung", "correct": true, "because": "Viele VMs gleichzeitig"}, {"text": "Geringer RAM", "correct": false, "because": "Mehr RAM nötig"}, {"text": "Langsame HDD", "correct": false, "because": "SSDs besser"}]');
